#include <stdio.h>

int sum_from(int fish[], int start, int count) {
    int sum = 0;
    for (int i = start; i < count; i++) {
        sum += fish[i];
    }
    return sum;
}

int main(void) {
    int fish[5] = {3, 1, 4, 1, 5};
    printf("总数是 %d\n", sum_from(fish, 1, 5));
    return 0;
}
